INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N076-01','CN0331','S076-01','同址历史设计','工程概况、水平衡、废水章节','租赁格林沃特；新水499.83m³/d、循环6259.05、总6758.88，原文重复利用率92.96%与按量比值略有差异；外排319.69；总投资非污水投资。纯水RO 10t/h为制水，不作工业污水膜。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-02','CN0244','S076-01','同址归属','项目概况','拓思历史租赁；分主体/项目记录，不推断独立厂区及格林沃特实际设备。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-03','CN0331','S076-02','扩建公示','转载正文','同址两期再生、新剂各1万吨/年；非批复、非投运；与2019历史设计不可直接相加。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N076-04','CN0332','S076-03','设计水量及工艺','3.4.2、表3.4-8/10/11','160m³/d能力、134m³/d处理，40187.6m³/a；65%回用、35%浓水；设计总排14545.66m³/a；原表单位及COD级间差异保留；截图超时，正文可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-05','CN0332','S076-04','许可线索','公开许可信息','2万吨废SCR处置许可线索；不替代实际产量，需核现行期限及年度运行。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-06','CN0014','S076-05','可研问题边界','采购计划转载','催化剂废水与炼油相关水混合；披露总氮脱除不足和全盐量风险，不能推断实际超标、全站无膜或设备选型。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N076-07','CN0014','S076-07','采购节点','候选人公示','11月25–30候选人公示；可研并非工程中标，未获实际运行成本；12月3日后定向查结果。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N076-08','CN0163','S076-08','建成规模','集团报道','板式SCR 30000m³/a、再生10000m³/a；网站路径年月，正文日期待核；非实际产量。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N076-09','CN0163','S076-09','地址核对','联合采购转载','南京将军大道536号与江苏装备盱眙不同地址；不把联合采购量算作南京能力。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N076-10','CN0333','S076-10','生产线索','采购及集团报道','SCR生产采购、2025设备监控报道；现有线体、许可、产能及污水站未核。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N076-11','CN0333','S076-13','环保改造','失败公告','未取得成交或具体污水介质；不认定为膜设备招标。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N076-12','CN0334','S076-14','弱候选','项目索引','拟8万吨/年废SCR，二次公示仅聚合索引，原件和厂址待核，不计在产。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N076-13','CN0212','W03S33','续证纠正','官方实时许可名录','2026-07-30至2031-07-29；HW50 3000+2500=5500，另HW35 7500；历史2025 HW50 12500保留。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-14','CN0210','W03S33','许可期限','官方实时许可名录','S42-09-81-0157，2026-10-15至2027-10-15；HW50/HW46混合10300已录不重复。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-15','CN0010','S076-16','批准及建设边界','审批表第5项、W03S01历史项目回顾','2025-06-20批准，2026年1月报告仍待建；吸附剂不计新催化剂；2026年9月重新申请排污许可，不等于项目已投产。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N076-16','CN0010','S076-15','分质回用','拟审批第2项','设备场地冲洗、含镍初雨分别回用；化验水及其他初雨除磷沉淀，生活生化后与公辅排水纳管；环保总投资162.01万元非污水投资。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
